import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.il0noOp3.js";const g=JSON.parse('{"title":"Configuration and report tiers","description":"Saving and loading an assessment configuration, and the report tiers each run can emit.","frontmatter":{"description":"Saving and loading an assessment configuration, and the report tiers each run can emit."},"headers":[],"relativePath":"assessment/configuration.md","filePath":"assessment/configuration.md"}'),o={name:"assessment/configuration.md"};function r(i,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="configuration-and-report-tiers" tabindex="-1">Configuration and report tiers <a class="header-anchor" href="#configuration-and-report-tiers" aria-label="Permalink to &quot;Configuration and report tiers&quot;">​</a></h1><p>How to pin an assessment&#39;s configuration so a run is reproducible, and what each output tier produces.</p><h2 id="assessment-config-load-save" tabindex="-1">Assessment config load/save <a class="header-anchor" href="#assessment-config-load-save" aria-label="Permalink to &quot;Assessment config load/save&quot;">​</a></h2><p><code>Import-ScoutConfig</code> / <code>Export-ScoutConfig</code> (AB#373–375) let you save and reload the effective assessment config — an alternative benchmark, rule-selection glob patterns, and per-rule threshold overrides — as a single JSON file, mirroring exactly what the engine already consumes (no new schema invented):</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Load a config (falls back to the built-in ALZ reference benchmark if the</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># file is absent, missing, or unparsable -- never throws)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Import-ScoutConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ConfigPath .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">my</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Round-trip: save the effective config back out</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Export-ScoutConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Config $config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">my</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Every key (<code>benchmark</code>, <code>rulePatterns</code>, <code>ruleOverrides</code>) is optional and independently overridable. A missing/invalid <code>-ConfigPath</code> degrades to &quot;run with defaults&quot; with a <code>Write-Warning</code> rather than aborting the assessment.</p><h2 id="report-tiers" tabindex="-1">Report tiers <a class="header-anchor" href="#report-tiers" aria-label="Permalink to &quot;Report tiers&quot;">​</a></h2><blockquote><p><strong>The React report is the deliverable. Every other rendered format is <em>coming soon</em>.</strong></p><p>Azure Scout now produces <strong>one</strong> report: a self-contained single-page HTML/React document that hosts the inventory and every assessment behind one adaptive shell, and exports to PDF, Word, Markdown and CSV from the page itself. The standalone document renderers are being rebuilt to generate <strong>from</strong> that report rather than alongside it, and are on hold in the meantime (<strong>AB#6922</strong>).</p><p>Asking for a held format by name still binds — the run warns, skips it, and renders the React report so you always get a deliverable. <code>-OutputFormat All</code> renders the React report plus the machine-readable data exports.</p></blockquote><h3 id="available-now" tabindex="-1">Available now <a class="header-anchor" href="#available-now" aria-label="Permalink to &quot;Available now&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Output</th><th>Notes</th></tr></thead><tbody><tr><td><strong>React</strong></td><td><code>report-react.html</code></td><td><strong>The deliverable.</strong> Self-contained (CSS/JS inline, findings embedded as a JSON blob, no external/CDN requests). Adaptive navigation built from what actually ran — inventory only, inventory + Entra, or inventory + assessments with per-assessment detail. Each assessment answers what was run, what was found, and what to fix against CAF/WAF, with every score shown alongside its own arithmetic and what was excluded from the denominator. VNet topology and MG-hierarchy diagrams, KPI cards, governance section, per-section search/filter, sortable findings with evidence drill-down, and a Drift tab (see <a href="#cross-run-drift">Cross-run drift</a>).</td></tr><tr><td>JSON</td><td><code>findings.json</code></td><td>The machine-readable contract — full assessment metadata, scores, and findings. Data, not a document; never held.</td></tr><tr><td>JSON evidence</td><td><code>evidence.json</code> (<code>Export-JsonEvidence</code>)</td><td>Resources-only export of the raw <code>collect.json</code> data (<strong>AB#396</strong>) — no assessment metadata, scores, or findings. For callers that just want the discovered resources as JSON.</td></tr></tbody></table><h3 id="coming-soon" tabindex="-1">Coming soon <a class="header-anchor" href="#coming-soon" aria-label="Permalink to &quot;Coming soon&quot;">​</a></h3><p>These renderers exist and are still tested, but are <strong>not emitted</strong> while the reporting engine is rebuilt. They will return generated from the React report&#39;s model, so a document and the page it came from can no longer disagree.</p><table tabindex="0"><thead><tr><th>Tier</th><th>Output</th><th>Status</th></tr></thead><tbody><tr><td>PDF</td><td><code>assessment_report.pdf</code></td><td><strong>Coming soon.</strong> Export to PDF from the React report today.</td></tr><tr><td>Word</td><td><code>assessment_report.docx</code></td><td><strong>Coming soon.</strong> Export to Word from the React report today; a native <code>.docx</code> is tracked as <strong>AB#6923</strong>.</td></tr><tr><td>Excel</td><td><code>assessment_evidence.xlsx</code></td><td><strong>Coming soon.</strong> Export findings to CSV from the React report today.</td></tr><tr><td>PowerPoint</td><td><code>assessment_deck.pptx</code></td><td><strong>Coming soon.</strong></td></tr><tr><td>Power BI</td><td><code>powerbi/*.csv</code> + <code>.pbit</code></td><td><strong>Coming soon.</strong></td></tr><tr><td>HTML</td><td><code>report.html</code></td><td><strong>Coming soon</strong> — superseded by the React report.</td></tr><tr><td>ECharts dashboard</td><td><code>assessment_dashboard.html</code></td><td><strong>Coming soon.</strong></td></tr><tr><td>Governance report</td><td><code>governance_report.html</code></td><td><strong>Coming soon.</strong></td></tr></tbody></table>`,13)])])}const m=t(o,[["render",r]]);export{g as __pageData,m as default};
